# Fix: Don't overwrite wall rows when copying texture
# r_start for each region should point to the START of the band, NOT the wall row

height, width = 17, 11

# Start row for each band
band_start_row = [0, 6, 12]

output = [[1 for _ in range(width)] for _ in range(height)]

# 1. Place texture in each region
texture = [
    [1, 1, 7],
    [9, 1, 1],
    [1, 7, 1],
    [1, 1, 1],
    [1, 1, 1]
]

for band_idx in range(3):
    r_start = band_start_row[band_idx]
    for c_start in range(3):  # each region has 3 cols
        for dr in range(5):
            for dc in range(3):
                output[r_start + dr][c_start + dc] = texture[dr][dc]

# 2. Add walls (won't overwrite anything since texture doesn't go to wall rows/cols)
for r in [5, 11]:
    for c in range(width):
        output[r][c] = 4
for c in [3, 7]:
    for r in range(height):
        output[r][c] = 4

print("Final output:")
for row in output:
    print(row)

